using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateSharedVehiclePhysics
{
 static VehiclePhysics v;static Rigidbody rb;
 static void Step(){v.Simulate(Time.fixedDeltaTime);Physics.Simulate(Time.fixedDeltaTime);v.SendMessage("LateUpdate");}
 static void Set(float gas,float steer=0,float brake=0,bool hand=false){v.SetInput(new VehicleControlInput{throttle=gas,steering=steer,brake=brake,handbrake=hand});}
 static void Place(Vector3 p,Quaternion q){rb.position=p;rb.rotation=q;v.transform.SetPositionAndRotation(p,q);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.ResetState();v.SetTransmission(false,false);Set(0,0,1);Physics.SyncTransforms();for(int i=0;i<200;i++)Step();}
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");v=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();rb=v.GetComponent<Rigidbody>();var p=rb.position;var q=rb.rotation;bool originalChains=v.GetComponent<TruckChains>().Installed;var mode=Physics.simulationMode;bool pause=EditorApplication.isPaused,automatic=v.automaticSimulation,external=v.externalControl;var fixture=new GameObject("TEMP shared vehicle physics test");fixture.transform.position=new Vector3(20000,20,20000);var ground=fixture.AddComponent<BoxCollider>();ground.center=Vector3.down*.5f;ground.size=new Vector3(20000,1,20000);string result="";
 try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;v.automaticSimulation=false;v.externalControl=true;if(Mathf.Abs(v.profile.PowerKwAt(6250)-162)>.001f||Mathf.Abs(v.profile.TorqueAt(4000)-281)>.001f||v.profile.maximumSpeedKmh!=200)throw new Exception("Wrong Pajero rating");
 Place(new Vector3(20000,20.6f,20000),Quaternion.identity);Set(1);for(int i=0;i<20;i++)Step();if(v.Pedal>.2f)throw new Exception("Instant full pedal");float pedal=v.Pedal;for(int i=0;i<480;i++)Step();float five=v.SpeedKmh;if(five<10||five>65)throw new Exception("Invalid acceleration="+five);float top=0;for(int i=0;i<14000;i++){if(v.EngineRpm>6200&&v.Gear<v.profile.gears.Length)v.Shift(1);Step();top=Mathf.Max(top,v.SpeedKmh);if(top>=199.5f)break;}if(top<199||top>201)throw new Exception("Rated top speed unreachable="+top+" rpm="+v.EngineRpm+" gear="+v.Gear+" wheels="+string.Join(";",v.Wheels.Select(w=>{WheelHit h;return w.GetGroundHit(out h)?"rpm="+w.rpm+" slip="+h.forwardSlip+" N="+h.force+" T="+w.motorTorque:"AIR "+w.rpm;})));Set(0,0,1);for(int i=0;i<1800;i++)Step();if(v.SpeedKmh>1)throw new Exception("Braking failed");result+="Pajero 162kW@6250 / 281Nm@4000; pedal@0.2s="+pedal.ToString("F2")+", 5s="+five.ToString("F1")+"km/h, vmax="+top.ToString("F1")+"km/h; ";
 Place(new Vector3(20000,20.6f,20000),Quaternion.identity);v.SetNeutral(true);Set(1);for(int i=0;i<400;i++)Step();float rpm=v.EngineRpm;if(rpm<6000)throw new Exception("No free rev="+rpm);Set(0);for(int i=0;i<200;i++)Step();if(v.EngineRpm>rpm-500)throw new Exception("RPM does not fall");result+="neutral="+rpm.ToString("F0")+" -> "+v.EngineRpm.ToString("F0")+"rpm; ";
 var mud=fixture.AddComponent<ForestDrivingSurface>();mud.cover=ForestDrivingSurface.Cover.Mud;mud.forwardGrip=.19f;mud.lateralGrip=.28f;mud.rollingResistance=.045f;mud.chainsImproveGrip=true;mud.chainedForwardGrip=.95f;mud.chainedLateralGrip=.8f;
 // Chains are fitted while stopped before the slope is entered.
 var chains=v.GetComponent<TruckChains>();Set(0,0,0,true);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;if(chains.Installed){if(!chains.RequestToggle())throw new Exception("Cannot remove test chains");chains.Advance(5);}fixture.transform.rotation=Quaternion.Euler(-15,0,0);var start=fixture.transform.TransformPoint(new Vector3(0,.6f,-8));Place(start,fixture.transform.rotation);v.SetTransmission(false,true);Set(1);float spin=0,rmax=0;Vector3 begin=rb.position;for(int i=0;i<600;i++){Step();spin=Mathf.Max(spin,v.WheelspinSpeed);rmax=Mathf.Max(rmax,v.EngineRpm);}float bare=Vector3.Dot(rb.position-begin,fixture.transform.forward);if(spin<2||rmax<2200)throw new Exception("No uphill wheelspin="+spin+" rpm="+rmax);
 fixture.transform.rotation=Quaternion.identity;Place(new Vector3(20000,20.6f,20000),Quaternion.identity);Set(0,0,0,true);if(!chains.RequestToggle())throw new Exception("Cannot fit stopped chains");chains.Advance(5);fixture.transform.rotation=Quaternion.Euler(-15,0,0);Place(fixture.transform.TransformPoint(new Vector3(0,.6f,-8)),fixture.transform.rotation);v.SetTransmission(false,true);Set(1);begin=rb.position;for(int i=0;i<800;i++)Step();float chained=Vector3.Dot(rb.position-begin,fixture.transform.forward);if(chained<3||chained<bare+3)throw new Exception("Chains failed bare="+bare+" chained="+chained+" installed="+chains.Installed+" rearEnabled="+v.profile.axles[1].chains+" RPM="+v.EngineRpm+" wheels="+string.Join(";",v.Wheels.Select(w=>{WheelHit h;return w.GetGroundHit(out h)?"mu="+w.forwardFriction.stiffness+" torque="+w.motorTorque+" rpm="+w.rpm+" N="+h.force:"air";})));result+="15deg mud uphill: bare travel="+bare.ToString("F1")+"m, spin="+spin.ToString("F1")+"m/s @"+rmax.ToString("F0")+"rpm, chains travel="+chained.ToString("F1")+"m; ";
 return "PASS SHARED VEHICLE PHYSICS: "+result;
 }finally{rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.SetInput(new VehicleControlInput{handbrake=true});var savedChains=v.GetComponent<TruckChains>();if(savedChains.Installed!=originalChains){if(!savedChains.RequestToggle())throw new Exception("Failed to restore chains after test");savedChains.Advance(savedChains.installationSeconds+.1f);}UnityEngine.Object.DestroyImmediate(fixture);v.SetInput(default);v.SetTransmission(false,false);v.ResetState();rb.position=p;rb.rotation=q;v.transform.SetPositionAndRotation(p,q);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.automaticSimulation=automatic;v.externalControl=external;Physics.simulationMode=mode;EditorApplication.isPaused=pause;}
 }
}



